darlehen_verzugshemmungszeitraum <- function(anspruch_entstanden_am=NULL, erster_verzugshemmungstag=NULL, feststellung_letzter_hemmungstag=NULL, betrachtung_bis=NULL, einordnungsnachweis=NULL) {
 a <- .datum(anspruch_entstanden_am,'anspruch_entstanden_am');v <- .datum(erster_verzugshemmungstag,'erster_verzugshemmungstag');b <- .datum(betrachtung_bis,'betrachtung_bis');.text(einordnungsnachweis,'einordnungsnachweis')
 f <- if(is.null(feststellung_letzter_hemmungstag)) NULL else .datum(feststellung_letzter_hemmungstag,'feststellung_letzter_hemmungstag')
 if(v<a||b<a||(!is.null(f)&&(f<a||f>b))) .fehler('zeitfolge','Verzug/Betrachtung nicht vor Entstehung; Feststellung innerhalb beobachteter Zeit erforderlich.')
 g <- .frist(anspruch_entstanden_am,10,'jahre','ereignis');ende <- if(is.null(f)) min(g,b) else min(g,b,f)
 wert <- list(zehnjahresgrenze=format(g,'%Y-%m-%d'),hemmungszeitraeume=if(v>ende) list() else list(list(erster_gehemmter_tag=format(v,'%Y-%m-%d'),letzter_gehemmter_tag=format(ende,'%Y-%m-%d'))))
 eingaben <- list(anspruch_entstanden_am=anspruch_entstanden_am, erster_verzugshemmungstag=erster_verzugshemmungstag, feststellung_letzter_hemmungstag=feststellung_letzter_hemmungstag, betrachtung_bis=betrachtung_bis, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,"daten_und_intervalle","BGB_DARLEHEN_VERZUGSHEMMUNGSZEITRAUM",eingaben,list(list(operation="Zehnjahresgrenze ab Anspruchsentstehung berechnen und beobachtetes Verzugshemmungsintervall an Feststellung beziehungsweise Hoechstgrenze abschneiden.")),eingaben)
 ergebnis$hinweise <- list("\u00a7497III3: vom rechtlich normalisierten Verzugsbeginn bis qualifizierter Feststellung197I3bis5, hoechstens zehn Jahre ab Entstehung des einzelnen Anspruchs. Vorhandener Kalenderkern berechnet Zehnjahresgrenze, Intervall wird am fruehesten von Feststellung, Hoechstgrenze und Betrachtungsende abgeschnitten. Ohne Feststellung nur beobachtetes Intervall, kein behauptetes endgueltiges Verjaehrungsende. Unterschiedlich entstandene Einzelansprueche getrennt behandeln; Hemmung nach209 danach mit vorhandenem Kern kombinieren. Tagesnormalisierung einschliesslich Randtage rechtlich belegen; kein pauschales Aufrunden untertaegiger Ereignisse. Auch497IV nimmt III3nicht aus, wohingegen III5Titel-Hauptforderung-Zinsen-Ausnahme zu beachten ist. Keine persoenliche oder sachliche Anwendbarkeit automatisch feststellen, keine Hemmung einer schon abgelaufenen Frist.")
 ergebnis
}
